1	import type {WebSocket} from 'ws';
2	import {createChatOrchestrator} from '../orchestration/chatOrchestrator.js';
3	import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
4	import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
5	import {setLogger} from '../shared/logger.js';
6	import type {AIProvider} from '../types/ai.js';
7	import type {WsAuthenticator} from '../types/auth.js';
8	import type {HalServer} from './createServer.js';
9	import {announcedId, askOnOpen, deferred, startEngineWith, stopEngines} from './wsTestSupport.js';
10	
11	interface Interruption {
12	  close: (client: WebSocket, hal: HalServer) => void;
13	  wsAuth?: WsAuthenticator;
14	  token?: string;
15	}
16	
17	// One question whose socket `close` shuts once the first word has arrived; resolves after the abandoned run has ended.
18	async function interruptedTurn({close, wsAuth, token}: Interruption) {
19	  const {provider, gate, pulled, state} = gatedProvider();
20	  const hooksSeen = {afterSession: 0, onError: 0};
21	  const finished = deferred();
22	  const disconnected = deferred();
23	  const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'Close test.'}), undefined, {
24	    hooks: {
25	      afterSession: async () => {
26	        hooksSeen.afterSession++;
27	        finished.release();
28	      },
29	      onError: async () => void hooksSeen.onError++,
30	    },
31	  });
32	  const sessionStore = new InMemorySessionStore();
33	  const onDisconnect = () => disconnected.release();
34	  const {url, hal} = await startEngineWith({sessionStore, orchestrator, onDisconnect, ...(wsAuth ? {wsAuth} : {})});
35	  const {client, finished: answering} = askOnOpen(url, {until: 'entry_delta', token});
36	  const sessionId = announcedId(client);
37	  await answering;
38	  await closeMidAnswer(() => close(client, hal), {disconnected, gate, finished});
39	
40	  const session = await sessionStore.get(sessionId());
41	  return {sessionId: sessionId(), pulled, returned: state.returned, hooksSeen, entries: session?.entries};
42	}
43	
44	type Deferred = ReturnType<typeof deferred>;
45	
46	// The provider may go on only once the server has seen the close, so whatever it does next happens after it.
47	async function closeMidAnswer(
48	  close: () => void,
49	  {disconnected, gate, finished}: {disconnected: Deferred; gate: Deferred; finished: Deferred}
50	): Promise<void> {
