import {validateMessage} from './validation.js';

// One wire name for the client frame: the alias is gone, and the frame the validator returns is the exported shape.

describe('the websocket frame validator', () => {
  it('accepts user_message and returns the frame the exported union describes', () => {
    const result = validateMessage({type: 'user_message', content: 'hello'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('rejects send_message, which is no longer a wire name', () => {
    const result = validateMessage({type: 'send_message', content: 'hello'});

    expect(result).toEqual({valid: false, error: 'Unknown message type: send_message'});
  });

  it('drops any field the frame does not define, rather than forwarding it', () => {
    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });
});

// A list request asks by shape alone: whose conversations are listed is the connection's, never the frame's.

describe('a list_sessions frame', () => {
  const cursor = {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's3'};

  it('accepts a bare frame, a non-negative integer limit and a before cursor, and strips fields it does not define', () => {
    const accepted = [
      validateMessage({type: 'list_sessions'}),
      validateMessage({type: 'list_sessions', limit: 0}),
      validateMessage({type: 'list_sessions', limit: 10, before: cursor, userId: 'u2'}),
    ];

    expect(accepted).toEqual([
      {valid: true, data: {type: 'list_sessions'}},
      {valid: true, data: {type: 'list_sessions', limit: 0}},
      {valid: true, data: {type: 'list_sessions', limit: 10, before: cursor}},
    ]);
  });

  it('accepts a before cursor whose updatedAt is an epoch number, as a summary that went through JSON may carry either', () => {
    const result = validateMessage({type: 'list_sessions', before: {updatedAt: 1767225600000, sessionId: 's3'}});

    expect(result).toEqual({
      valid: true,
      data: {type: 'list_sessions', before: {updatedAt: 1767225600000, sessionId: 's3'}},
    });
  });

  it('rejects a limit that is not a non-negative integer, naming the field', () => {
    const rejected = ['ten', -1, 1.5].map(limit => validateMessage({type: 'list_sessions', limit}));

    expect(rejected).toEqual([
      {valid: false, error: expect.stringContaining('limit')},
      {valid: false, error: expect.stringContaining('limit')},
      {valid: false, error: expect.stringContaining('limit')},
    ]);
  });

  it('rejects a before that is not an object or carries a sessionId outside 1-128 chars or an updatedAt naming no moment', () => {
    const bad = [
      'not-an-object',
      {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''},
      {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)},
      {updatedAt: 'not-a-date', sessionId: 's1'},
      {updatedAt: true, sessionId: 's1'},
    ];
    const rejected = bad.map(before => validateMessage({type: 'list_sessions', before}));

    expect(rejected).toEqual(bad.map(() => ({valid: false, error: expect.stringContaining('before')})));
  });
});

