import type {IncomingMessage} from '../../types/messages.js';
import type {SessionCursor} from '../../types/sessionStore.js';

const MAX_CONTENT_LENGTH = 10000;
// The bound the resume path already puts on a client-supplied session id (specs/hal-engine-websocket-protocol/spec.md).
const MAX_SESSION_ID_LENGTH = 128;
const LIMIT_ERROR = 'list_sessions limit must be a non-negative integer';
const CURSOR_ERROR = 'list_sessions before must be a cursor of updatedAt and sessionId';
const CURSOR_ID_ERROR = 'list_sessions before.sessionId must be a string of 1 to 128 characters';
const CURSOR_MOMENT_ERROR = 'list_sessions before.updatedAt must be a string or number a Date parses';

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

// One validator per wire name: the table replaces a switch that reopened on every new frame type.
const FRAME_VALIDATORS: Record<string, (message: Record<string, unknown>) => ValidationResult> = {
  user_message: validateUserMessage,
  ping: validatePingMessage,
  list_sessions: validateListSessionsMessage,
};

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  const validate = FRAME_VALIDATORS[message.type];
  if (!validate) return {valid: false, error: `Unknown message type: ${message.type}`};
  return validate(message);
}

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  const trimmed = message.content.trim();

  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

// Validation is static and has no config: a frame the feature refuses is answered by the handler, not turned away here.
function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const limit = limitOf(message.limit);
  if (typeof limit === 'string') return {valid: false, error: limit};

  const cursor = cursorOf(message.before);
  if (typeof cursor === 'string') return {valid: false, error: cursor};

  return {valid: true, data: {type: 'list_sessions', limit, before: cursor}};
}

// A field a frame omits is none given; one present must still be usable, and the error names the field.
function limitOf(limit: unknown): number | string | undefined {
  if (limit === undefined) return undefined;
  const integer = typeof limit === 'number' && Number.isInteger(limit) && limit >= 0;
  return integer ? limit : LIMIT_ERROR;
}

// A cursor the frame cleared: the store's paging value, or the error text to reject the frame with.
function cursorOf(before: unknown): SessionCursor | string | undefined {
  if (before === undefined) return undefined;
  if (!isCursorFrame(before)) return CURSOR_ERROR;
  if (!isCursorId(before.sessionId)) return CURSOR_ID_ERROR;
  if (!isCursorMoment(before.updatedAt)) return CURSOR_MOMENT_ERROR;
  return {updatedAt: before.updatedAt, sessionId: before.sessionId};
}

function isCursorFrame(before: unknown): before is Record<string, unknown> {
  return typeof before === 'object' && before !== null;
}

function isCursorId(sessionId: unknown): sessionId is string {
  return typeof sessionId === 'string' && sessionId.length > 0 && sessionId.length <= MAX_SESSION_ID_LENGTH;
}

function isCursorMoment(updatedAt: unknown): updatedAt is string | number {
  if (typeof updatedAt === 'number') return Number.isFinite(updatedAt);
  return typeof updatedAt === 'string' && Number.isFinite(Date.parse(updatedAt));
}

